<script setup>
import { reactive,ref,watch,onMounted,onUnmounted } from 'vue';import { useRoute,useRouter } from 'vue-router';import { useClinicContextStore } from '../../stores/clinicContext';import { useDoctorStore } from '../../stores/doctors';import DoctorTable from '../../components/doctors/DoctorTable.vue';import AppIcon from '../../components/ui/AppIcon.vue';import FormErrors from '../../components/ui/FormErrors.vue';
const context=useClinicContextStore(),store=useDoctorStore(),route=useRoute(),router=useRouter();const defaults={search:'',specialty_id:'',status:'',availability:'',branch_id:String(context.data.branch.id),page:'1',per_page:'25'};
const filters=reactive({...defaults,...route.query}),error=ref(null),more=ref(false);let timer;
async function load(){await store.list(filters);}function apply(page=1){filters.page=String(page);router.replace({query:Object.fromEntries(Object.entries(filters).filter(([,v])=>v!==''))});}function search(){clearTimeout(timer);timer=setTimeout(()=>apply(),350);}function reset(){Object.assign(filters,defaults);apply();}
async function initialize(){error.value=null;try{await store.loadOptions();await load();}catch(e){error.value=e;}}onMounted(initialize);onUnmounted(()=>clearTimeout(timer));watch(()=>route.query,q=>{Object.assign(filters,defaults,q);load();});
</script>
<template><div class="patient-page-header"><div><p class="patient-breadcrumb"><RouterLink to="/app/dashboard">Dashboard</RouterLink><span>/</span>Doctors / Clinicians</p><h1>Doctors / Clinicians</h1><p>Manage your clinic’s doctors and clinical staff.</p></div><RouterLink v-if="context.can('doctors.create')" to="/app/doctors/create" class="btn">＋ Add Doctor</RouterLink></div><div class="clinic-kpis"><section v-for="card in [['Total Doctors','total','members','mint'],['Active Doctors','active','doctor','blue'],['Specializations','specializations','patient','blue'],['On Leave','on_leave','calendar','patient-rose']]" :key="card[1]" class="clinic-panel clinic-kpi"><span class="clinic-kpi-icon" :class="card[3]"><AppIcon :name="card[2]" :size="28"/></span><div><h2>{{card[0]}}</h2><strong>{{store.stats?.[card[1]] ?? '—'}}</strong><p>{{card[1]==='specializations'?'Different specialties':'In the selected branch'}}</p></div></section></div>
<form class="clinic-panel patient-filters doctor-filters" @submit.prevent="apply()"><input v-model="filters.search" aria-label="Search clinicians" class="filter-input" type="search" placeholder="Search by name, specialty, phone or email..." @input="search"><select v-model="filters.specialty_id" class="compact-select" aria-label="Specialization filter" @change="apply()"><option value="">Specialization</option><option v-for="s in store.options?.specialties" :key="s.id" :value="s.id">{{s.name}}</option></select><select v-model="filters.status" class="compact-select" aria-label="Status filter" @change="apply()"><option value="">Status</option><option value="active">Active</option><option value="inactive">Inactive</option></select><select v-model="filters.availability" class="compact-select" aria-label="Availability filter" @change="apply()"><option value="">Availability</option><option v-for="v in ['available','in_consultation','unavailable','on_leave']" :key="v" :value="v">{{v.replaceAll('_',' ')}}</option></select><button class="btn-secondary" type="button" :aria-expanded="more" @click="more=!more">More Filters</button><button class="btn-secondary" type="button" @click="reset">Reset</button><label v-if="more" class="field w-full">Branch<select v-model="filters.branch_id" @change="apply()"><option v-for="branch in context.data.branches" :key="branch.id" :value="branch.id">{{branch.name}}</option></select></label></form>
<FormErrors :error="error || store.error"/><section class="clinic-panel patient-list-panel"><div v-if="store.busy" class="p-6 space-y-3" role="status"><div v-for="i in 5" :key="i" class="h-12 animate-pulse rounded-lg bg-slate-100"></div></div><div v-else-if="error || store.error" class="empty-state"><button class="btn" @click="initialize">Try again</button></div><DoctorTable v-else-if="store.rows.length" :doctors="store.rows" @changed="load"/><div v-else class="clinic-empty"><AppIcon name="doctor" :size="36"/><strong>{{store.stats?.total?'No doctors match your search.':'No doctors or clinicians have been added yet.'}}</strong><RouterLink v-if="context.can('doctors.create')" class="btn" to="/app/doctors/create">Add First Doctor</RouterLink></div><div v-if="store.meta && !store.busy" class="patient-pagination"><span>Showing {{store.meta.from || 0}} to {{store.meta.to || 0}} of {{store.meta.total}} doctors</span><label>Per page <select v-model="filters.per_page" class="compact-select" @change="apply()"><option>25</option><option>50</option><option>100</option></select></label><button class="btn-secondary" :disabled="store.meta.current_page===1" @click="apply(store.meta.current_page-1)">Previous</button><span>{{store.meta.current_page}} / {{store.meta.last_page}}</span><button class="btn-secondary" :disabled="store.meta.current_page===store.meta.last_page" @click="apply(store.meta.current_page+1)">Next</button></div></section><div class="doctor-plan-panel"><AppIcon name="roles" :size="24"/><div><strong>Need to add more doctors?</strong><p>Your clinic uses {{store.options?.usage ?? '—'}} of {{store.options?.doctor_limit ?? 'unlimited'}} clinician places.</p></div><RouterLink v-if="context.allowed('settings')" class="btn-secondary" to="/app/settings">Manage Plan</RouterLink></div></template>
